window.products.push({"id":556638,"name":"Pressure Activated Mug Warmer – HOWAY Coffee Cup Warmer for Desk, 4 Hours Auto Shut Off, 2 Temperature Settings Control for Warm Hot Beverage, 110V","category":"homeandappliances","retail price":23.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71tFJnuH7hL._AC_SL1500_.jpg","description":"【Keep Beverages Warm】-Use this mug warmer to keep your coffee at a warm or hot temperature all the time, and no more cold drinks especially fast cooling in winter 【Two Temperature Settings】-Customize your beverage to an ultimate temperature-Blue light 104℉/40℃ or red light 140℉/60℃, which can meet your personal temperature preference for tea, cocoa or milk 【Pressure-Activated Technology】–The heating plate only heats up after you put the cup on it. When you lift up the cup, it will stop heating and goes standby 【Automatic Shut off】–This coffee warmer will automatically shut off after 4 hours of constantly working, so you are worry-free about forgetting to turn it off 【Power Supply】–The rated power of this cup warmer is 20W, voltage: 110V~120V. Comes with 1 year warranty, plus lifetime support provided by HOWAY","images":["https://m.media-amazon.com/images/I/71tFJnuH7hL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"HOWAY","source_asin":"B0B5W87V3G","category_path":"Home & Kitchen"},"sku":"BM-556638","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0B5W87V3G","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0B5W87V3G","price_pending":true,"merchant_ready":false});
